/**
     * Ermittelt die möglichen Jahre des zukünftigen neuen Gesamtplans als Array zurück (ein oder zwei Elemente).
     * Wenn es noch keinen Gesamtplan gibt, wird das aktuelle Jahr und das nächste Jahr zurückgegeben.
     * Wenn der letzte Gesamtplan einjährig war, wird das darauf folgende Jahr zurückgeben.
     * Wenn der letzte Gesamtplan zweijährig war, wird das dem zweiten Jahr folgende Jahr zurückgegeben.
     * @return int[] möglichen Jahre des zukünftigen neuen Gesamtplans
     */
    public static function getJahrNeuerGesamtplan(): array
    {
        $letzterGesamtplan = self::getLetzterGesamtPlan();
        if ($letzterGesamtplan == null) {
            $jahr = Tools::getCurrentYear();
            return [$jahr, $jahr + 1];
        }
        return $letzterGesamtplan->jahr2 === null ? [$letzterGesamtplan->jahr + 1] : [$letzterGesamtplan->jahr2 + 1];
    }

