    public static function checkAndGetGesamtPlan(int $jahr, ?Gesamtplan &$gesamtPlan): string
    {
        if ($jahr === 0) {
            $gesamtPlan = null;
            return 'Ungültiger Aufrufparameter. Der IT-Gesamtplan konnte nicht ermittelt werden.';
        }

        $gesamtPlan = GesamtPlan::getGesamtPlan($jahr);
        if ($gesamtPlan === null) {
            return "Ungültiger Aufruf. Der IT-Gesamtplan für das Jahr $jahr existiert nicht.";
        }

        if ($gesamtPlan->archived) {
            return "Ungültiger Aufruf. Der IT-Gesamtplan für das Jahr $jahr ist bereits archiviert und kann daher nicht bearbeitet werden.";
        }
        return "OK";
    }

